<?php namespace App\Features\Ai\Services;use App\Features\Ai\Contracts\AiClientInterface;use App\Features\Ai\DTO\GeneratedStockItem;use Illuminate\Support\Facades\Http;
class OpenAiStockGeneratorService implements AiClientInterface{public function generate(string $prompt):array{$key=config('openai.api_key');if(!$key)throw new \RuntimeException('OPENAI_API_KEY belum diatur.');$res=Http::withToken($key)->post('https://api.openai.com/v1/chat/completions',['model'=>config('openai.model'),'messages'=>[['role'=>'system','content'=>'Balas JSON array berisi item inventaris.'],['role'=>'user','content'=>$prompt]],'response_format'=>['type'=>'json_object']])->throw()->json();$content=$res['choices'][0]['message']['content']??'{}';$decoded=json_decode($content,true);$items=$decoded['items']??(array_is_list($decoded)?$decoded:[]);return array_map(fn($x)=>GeneratedStockItem::fromArray($x),$items);}}
